BEGIN TRY
    -- statements that may fail
    SELECT 1 / 0;
END TRY
BEGIN CATCH
    -- handle the error
    SELECT 'An error occurred.';
END CATCH;

BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE sales.accounts
    SET    balance = balance - 100
    WHERE  account_id = 1;

    UPDATE sales.accounts
    SET    balance = balance + 100
    WHERE  account_id = 2;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    SELECT ERROR_MESSAGE() AS ErrorMessage;
END CATCH;

IF @price < 0
    RAISERROR ('Price cannot be negative.', 16, 1);

-- Re-raising from CATCH:
BEGIN CATCH
    RAISERROR (
        ERROR_MESSAGE(),
        ERROR_SEVERITY(),
        ERROR_STATE()
    );
END CATCH;

BEGIN TRY
    -- some failing operation
    INSERT INTO sales.orders (bad_column) VALUES (1);
END TRY
BEGIN CATCH
    -- Simple: re-throw the original error as-is
    THROW;
END CATCH;
